import data from "../data/source-sound.json";

// The "Sound" section of a sources page (brand/SONIC-IDENTITY.md): every credit line, its page link and licence.
// data/source-sound.json is generated by RN_COLLINS hq/site/build_sound_credits.py for Reels whose sound RN approved.
export type SoundCredit = { credit: string; url: string; licence: string };

const pages = (data as { pages: Record<string, SoundCredit[]> }).pages;

export function soundFor(id: string): SoundCredit[] {
  return pages[id] ?? [];
}
